CREATE SCHEMA IF NOT EXISTS memory.demo;
CREATE TABLE IF NOT EXISTS memory.demo.audit_events AS
SELECT * FROM (VALUES
  (BIGINT '1', TIMESTAMP '2026-10-08 10:00:00 UTC', 'jsmith', 'login',  true,  DECIMAL '10.50', DOUBLE '0.10', DATE '2026-10-08', JSON '{"ip":"10.0.0.1"}', UUID '11111111-1111-4111-8111-111111111111', IPADDRESS '10.0.0.1'),
  (BIGINT '2', TIMESTAMP '2026-10-08 10:05:00 UTC', 'jsmith', 'read',   false, DECIMAL '0.00',  DOUBLE '0.40', DATE '2026-10-08', JSON '{"ip":"10.0.0.1"}', UUID '11111111-1111-4111-8111-111111111111', IPADDRESS '10.0.0.1'),
  (BIGINT '3', TIMESTAMP '2026-10-08 10:07:00 UTC', 'adoe',   'login',  true,  DECIMAL '99.99', DOUBLE '0.75', DATE '2026-10-09', JSON '{"ip":"10.0.0.2"}', UUID '33333333-3333-4333-8333-333333333333', IPADDRESS '10.0.0.2'),
  (BIGINT '4', TIMESTAMP '2026-10-08 10:09:00 UTC', 'adoe',   'delete', false, DECIMAL '5.25',  DOUBLE '0.90', DATE '2026-10-09', JSON '{"ip":"10.0.0.2"}', UUID '44444444-4444-4444-8444-444444444444', IPADDRESS '10.0.0.2')
) AS t (id, event_time, username, action, ok, amount, score, day, details, uid, ip);
